"use client";

import * as React from "react";
import { motion, type Variants } from "motion/react";
import { useRouter } from "next/router";

function cn(...classes: Array<string | undefined | null | false>) {
  return classes.filter(Boolean).join(" ");
}

export type CurvePageTransitionProps = {
  children: React.ReactNode;

  /** Map of pathname -> label shown while the curve covers the page.
   *  Unmapped paths fall back to the capitalized last URL segment. */
  routes?: Record<string, string>;

  /** Page background color behind the content */
  backgroundColor?: string;

  /** Color of the sweeping overlay curve (and its label backdrop) */
  curveColor?: string;

  className?: string;
};

/** Spread helper: wires a variants object to the standard three states. */
const anim = (variants: Variants) => ({
  variants,
  initial: "initial",
  animate: "enter",
  exit: "exit",
});

// NOTE: everything animates `y` (a compositor-friendly transform), never
// `top` — animating layout properties on viewport-sized elements forces a
// relayout every frame and visibly drops frames.

const text = (viewportH: number): Variants => ({
  initial: { opacity: 1, y: 0 },
  enter: {
    opacity: 0,
    y: -(viewportH * 0.5 + 150),
    transition: { duration: 0.75, delay: 0.35, ease: [0.76, 0, 0.24, 1] },
    transitionEnd: { y: 60 },
  },
  exit: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, delay: 0.4, ease: [0.33, 1, 0.68, 1] },
  },
});

const translate = (depth: number, viewportH: number): Variants => ({
  initial: { y: -depth },
  enter: {
    y: -viewportH,
    transition: { duration: 0.75, delay: 0.35, ease: [0.76, 0, 0.24, 1] },
    transitionEnd: { y: viewportH },
  },
  exit: {
    y: -depth,
    transition: { duration: 0.75, ease: [0.76, 0, 0.24, 1] },
  },
});

// page content parallax: eases upward while the sheet covers it on exit,
// and settles upward into place as the sheet peels away on enter
const content: Variants = {
  initial: { y: 150 },
  enter: {
    y: 0,
    // long exponential ease-out: most travel early, feathered landing
    transition: { duration: 1, delay: 0.35, ease: [0.16, 1, 0.3, 1] },
  },
  exit: {
    y: -120,
    // gentler in-out than the sheet's curve, slightly longer, so the
    // content glides rather than snaps while being covered
    transition: { duration: 0.85, ease: [0.65, 0, 0.35, 1] },
  },
};

const curve = (initialPath: string, targetPath: string): Variants => ({
  initial: { d: initialPath },
  enter: {
    d: targetPath,
    transition: { duration: 0.75, delay: 0.35, ease: [0.76, 0, 0.24, 1] },
  },
  exit: {
    d: initialPath,
    transition: { duration: 0.75, ease: [0.76, 0, 0.24, 1] },
  },
});

function defaultLabel(path: string) {
  if (path === "/") return "Home";
  const seg = path.split("/").filter(Boolean).pop() ?? "";
  return seg.charAt(0).toUpperCase() + seg.slice(1);
}

/**
 * Curve page-transition layout for the Pages Router, after Olivier Larose's
 * "Next.js Page Transition Guide". Wrap each page's content in this component
 * and mount <AnimatePresence mode="wait"> around <Component> in _app (see the
 * README) — on navigation a colored sheet with a curved edge sweeps over the
 * outgoing page, shows the route label, then peels away from the new page.
 */
export function CurvePageTransition({
  children,
  routes,
  backgroundColor,
  curveColor = "black",
  className,
}: CurvePageTransitionProps) {
  const router = useRouter();
  const [dimensions, setDimensions] = React.useState<{
    width: number | null;
    height: number | null;
  }>({ width: null, height: null });

  React.useEffect(() => {
    function resize() {
      setDimensions({ width: window.innerWidth, height: window.innerHeight });
    }
    resize();
    window.addEventListener("resize", resize);
    return () => window.removeEventListener("resize", resize);
  }, []);

  const label =
    routes?.[router.route] ??
    routes?.[router.asPath] ??
    defaultLabel(router.route);

  return (
    <div
      // overflow-y-clip: the content parallax translates the page down during
      // enter, and transformed boxes count toward scrollable overflow — without
      // the clip, a scrollbar flashes in for the duration of the transition
      className={cn("relative min-h-screen overflow-y-clip", className)}
      style={{ backgroundColor }}
    >
      {/* solid cover shown until the window is measured, so the first
          paint never flashes unstyled content before the SVG mounts */}
      <div
        className="pointer-events-none fixed top-0"
        style={{
          left: -5,
          width: "calc(100vw + 10px)",
          height: "calc(100vh + 600px)",
          backgroundColor: curveColor,
          opacity: dimensions.width === null ? 1 : 0,
          transition: "opacity 0s linear 0.1s",
          zIndex: 2,
        }}
      />
      <motion.p
        className="pointer-events-none absolute left-1/2 z-[3] -translate-x-1/2 -translate-y-1/2 text-center text-[length:clamp(1.5rem,5vw,2.875rem)] font-medium text-white"
        style={{ top: "50%" }}
        {...anim(text(dimensions.height ?? 800))}
      >
        {label}
      </motion.p>
      {dimensions.width !== null && dimensions.height !== null && (
        <SVG
          width={dimensions.width}
          height={dimensions.height}
          curveColor={curveColor}
        />
      )}
      <motion.div {...anim(content)}>{children}</motion.div>
    </div>
  );
}

function SVG({
  width,
  height,
  curveColor,
}: {
  width: number;
  height: number;
  curveColor: string;
}) {
  // The curved lip is 300px deep on desktop, but a fixed depth turns into a
  // deep bowl on narrow screens — scale it with the viewport width, and use
  // an even gentler ratio on phones.
  const depth = Math.min(300, Math.round(width / (width < 640 ? 6 : 4)));

  // The svg element is positioned 5px past both horizontal viewport edges
  // (see the style below) and the path fills that entire widened box —
  // subpixel rounding on scaled displays can otherwise leave a hairline gap
  // at the viewport edge, since the path clips to the svg's own bounds.
  const L = 0;
  const R = width + 10;

  // covering state: curved lips bulge `depth`px past the top and bottom edges
  const initialPath = `
    M${L} ${depth}
    Q${width / 2} 0 ${R} ${depth}
    L${R} ${height + depth}
    Q${width / 2} ${height + depth * 2} ${L} ${height + depth}
    L${L} 0
  `;

  // revealed state: bottom edge flattens against the viewport bottom
  const targetPath = `
    M${L} ${depth}
    Q${width / 2} 0 ${R} ${depth}
    L${R} ${height}
    Q${width / 2} ${height} ${L} ${height}
    L${L} 0
  `;

  return (
    <motion.svg
      className="pointer-events-none fixed"
      style={{
        top: 0,
        left: -5,
        width: "calc(100vw + 10px)",
        height: `calc(100vh + ${depth * 2}px)`,
        zIndex: 2,
        willChange: "transform",
      }}
      {...anim(translate(depth, height))}
    >
      <motion.path fill={curveColor} {...anim(curve(initialPath, targetPath))} />
    </motion.svg>
  );
}

# CurvePageTransition

A route-transition layout for the **Next.js Pages Router**: on navigation, a colored sheet with a curved edge sweeps over the outgoing page, shows the route's label, then peels away to reveal the new page. Port of the "Curve" transition from [Olivier Larose's Next.js Page Transition Guide](https://blog.olivierlarose.com/articles/nextjs-page-transition-guide).

## Dependencies

```bash
npm install motion
```

Also assumes **Next.js Pages Router** (`useRouter` from `next/router`) and Tailwind CSS (only utility classes; no theme tokens required).

## Integration

Two steps — the component wraps each page, and `_app.tsx` provides the enter/exit orchestration:

**1. `pages/_app.tsx`** — mount `AnimatePresence` around the page component and key it by route:

```tsx
import { AnimatePresence } from "motion/react";
import type { AppProps } from "next/app";

export default function App({ Component, pageProps, router }: AppProps) {
  return (
    <AnimatePresence mode="wait">
      <Component key={router.route} {...pageProps} />
    </AnimatePresence>
  );
}
```

**2. Each page** — wrap the content:

```tsx
import { CurvePageTransition } from "@/components/curve-page-transition/curve-page-transition";

const routes = { "/": "Home", "/about": "About" };

export default function About() {
  return (
    <CurvePageTransition routes={routes} backgroundColor="var(--background)">
      {/* page content */}
    </CurvePageTransition>
  );
}
```

## Props

- `routes` — map of pathname → label shown mid-transition. Unmapped paths fall back to the capitalized last URL segment.
- `backgroundColor` — page background behind the content.
- `curveColor` — the sweeping sheet's color (default `black`).
- `className` — extra classes for the page wrapper.

## Notes

- Page content gets a parallax slide (à la dennissnellenberg.com): it eases ~120px upward while the sheet covers it on exit, and settles upward into place from ~150px below as the sheet peels away on enter. Tune the `content` variants in the file to adjust the distances.
- Because the content wrapper animates `transform`, `position: fixed` elements inside the page are repositioned relative to it *during* the transition — keep persistent fixed UI (navbars etc.) outside the component.

- The label inherits `font-family` from its ancestors — wrap the component in your font provider's className to brand it.
- The overlay plays once on first load too (initial reveal). Pass `initial={false}` to `AnimatePresence` in `_app` to skip that.
- Pages should be at least viewport-height (the wrapper enforces `min-h-screen`); the label is centered and its size clamps between 24px and 46px with the viewport.
- The curve's depth scales with viewport width (capped at the original 300px), so phones get a gentle arc instead of a deep bowl.

"use client";

import * as React from "react";
import Link from "next/link";
import { useRouter } from "next/router";
import {
  AnimatePresence,
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
  type Variants,
} from "motion/react";

export type CurvedMenuItem = {
  title: string;
  href: string;
  target?: string;
};

export type CurvedMenuProps = {
  items?: CurvedMenuItem[];
  homepagePath?: string;
  revealAfterTarget?: string | null;
  navigationLabel?: string;
};

export const defaultCurvedMenuItems: CurvedMenuItem[] = [
  { title: "Home", href: "/", target: "home" },
  { title: "Work", href: "/works" },
  { title: "About", href: "/#about", target: "about" },
  { title: "Contact", href: "/contact" },
];

const EASE: [number, number, number, number] = [0.76, 0, 0.24, 1];
const MENU_COLOR = "#0c0c0e";
const MAGNET_SPRING = { stiffness: 260, damping: 20, mass: 0.35 };

const menuSlide: Variants = {
  initial: { x: "calc(100% + 120px)" },
  enter: {
    x: 0,
    transition: { duration: 0.8, ease: EASE },
  },
  exit: {
    x: "calc(100% + 120px)",
    transition: { duration: 0.7, ease: EASE },
  },
};

const backdrop: Variants = {
  initial: { opacity: 0 },
  enter: { opacity: 1, transition: { duration: 0.35 } },
  exit: { opacity: 0, transition: { duration: 0.35, delay: 0.15 } },
};

function createLinkSlide(itemCount: number): Variants {
  return {
    initial: { x: 72, opacity: 0 },
    enter: (index: number) => ({
      x: 0,
      opacity: 1,
      transition: {
        duration: 0.65,
        delay: 0.2 + index * 0.07,
        ease: [0.16, 1, 0.3, 1],
      },
    }),
    exit: (index: number) => ({
      x: 36,
      opacity: 0,
      transition: {
        duration: 0.3,
        delay: (itemCount - index - 1) * 0.025,
        ease: EASE,
      },
    }),
  };
}

const curve: Variants = {
  initial: { d: "M100 0 L100 100 Q-100 50 100 0" },
  enter: {
    d: "M100 0 L100 100 Q100 50 100 0",
    transition: { duration: 0.9, ease: EASE },
  },
  exit: {
    d: "M100 0 L100 100 Q-100 50 100 0",
    transition: { duration: 0.7, ease: EASE },
  },
};

function hrefPath(href: string) {
  return href.split("#")[0]?.split("?")[0] || "/";
}

function currentNavHref(
  pathname: string,
  asPath: string,
  items: CurvedMenuItem[],
  homepagePath: string,
) {
  if (pathname === homepagePath) {
    const hash = asPath.split("#")[1]?.split("?")[0];
    if (hash) {
      return items.find((item) => item.target === hash)?.href ?? homepagePath;
    }
    return (
      items.find(
        (item) => hrefPath(item.href) === homepagePath && item.target === "home",
      )?.href ?? homepagePath
    );
  }

  const candidates = items
    .filter((item) => hrefPath(item.href) !== homepagePath)
    .sort((a, b) => hrefPath(b.href).length - hrefPath(a.href).length);

  return (
    candidates.find((item) => {
      const path = hrefPath(item.href);
      return pathname === path || pathname.startsWith(`${path}/`);
    })?.href ?? null
  );
}

function targetTop(target: string) {
  if (target === "home") return 0;
  return document.getElementById(target)?.offsetTop ?? null;
}

function scrollToTarget(target: string, behavior: ScrollBehavior) {
  const top = targetTop(target);
  if (top === null) return false;
  window.scrollTo({ top, behavior });
  return true;
}

function CurvedEdge({ reduceMotion }: { reduceMotion: boolean }) {
  return (
    <svg
      aria-hidden="true"
      className="pointer-events-none absolute right-full top-0 h-full w-[clamp(84px,12vw,120px)] overflow-visible"
      style={{ color: MENU_COLOR }}
      viewBox="0 0 100 100"
      preserveAspectRatio="none"
    >
      <motion.path
        fill="currentColor"
        variants={reduceMotion ? undefined : curve}
        initial={reduceMotion ? false : "initial"}
        animate={reduceMotion ? undefined : "enter"}
        exit={reduceMotion ? undefined : "exit"}
        d={reduceMotion ? "M100 0 L100 100 Q35 50 100 0" : undefined}
      />
    </svg>
  );
}

export function CurvedMenu({
  items = defaultCurvedMenuItems,
  homepagePath = "/",
  revealAfterTarget = "works",
  navigationLabel = "Navigation",
}: CurvedMenuProps) {
  const router = useRouter();
  const reduceMotion = Boolean(useReducedMotion());
  const [isOpen, setIsOpen] = React.useState(false);
  const [hasReachedTrigger, setHasReachedTrigger] = React.useState(false);
  const [activeHref, setActiveHref] = React.useState<string | null>(() =>
    currentNavHref(router.pathname, router.asPath, items, homepagePath),
  );
  const [selectedHref, setSelectedHref] = React.useState<string | null>(
    activeHref,
  );
  const toggleRef = React.useRef<HTMLButtonElement | null>(null);
  const panelRef = React.useRef<HTMLElement | null>(null);
  const wasOpenRef = React.useRef(false);
  const pendingTargetRef = React.useRef<string | null>(null);
  const magneticX = useMotionValue(0);
  const magneticY = useMotionValue(0);
  const springX = useSpring(magneticX, MAGNET_SPRING);
  const springY = useSpring(magneticY, MAGNET_SPRING);
  const linkSlide = React.useMemo(() => createLinkSlide(items.length), [items.length]);

  const resetTogglePosition = React.useCallback(() => {
    magneticX.set(0);
    magneticY.set(0);
  }, [magneticX, magneticY]);

  const handleTogglePointerMove = React.useCallback(
    (event: React.PointerEvent<HTMLButtonElement>) => {
      if (reduceMotion || event.pointerType !== "mouse") return;

      const bounds = event.currentTarget.getBoundingClientRect();
      const offsetX = event.clientX - (bounds.left + bounds.width / 2);
      const offsetY = event.clientY - (bounds.top + bounds.height / 2);

      magneticX.set(offsetX * 0.28);
      magneticY.set(offsetY * 0.28);
    },
    [magneticX, magneticY, reduceMotion],
  );

  React.useEffect(() => {
    if (!router.isReady) return;
    const next = currentNavHref(
      router.pathname,
      router.asPath,
      items,
      homepagePath,
    );
    setActiveHref(next);
    setSelectedHref(next);
  }, [homepagePath, items, router.asPath, router.isReady, router.pathname]);

  React.useEffect(() => {
    if (router.pathname !== homepagePath || revealAfterTarget === null) {
      setHasReachedTrigger(true);
      return;
    }

    setHasReachedTrigger(false);
    let observer: IntersectionObserver | undefined;
    let frame = 0;
    let attempts = 0;

    const attach = () => {
      const trigger = document.getElementById(revealAfterTarget);
      if (!trigger) {
        if (attempts < 180) {
          attempts += 1;
          frame = window.requestAnimationFrame(attach);
        }
        return;
      }

      observer = new IntersectionObserver(
        ([entry]) => {
          if (!entry) return;
          setHasReachedTrigger(
            entry.isIntersecting || entry.boundingClientRect.top < 0,
          );
        },
        { threshold: 0.01 },
      );
      observer.observe(trigger);
    };

    frame = window.requestAnimationFrame(attach);
    return () => {
      window.cancelAnimationFrame(frame);
      observer?.disconnect();
    };
  }, [homepagePath, revealAfterTarget, router.pathname]);

  React.useEffect(() => {
    const close = () => setIsOpen(false);
    router.events.on("routeChangeStart", close);
    return () => router.events.off("routeChangeStart", close);
  }, [router.events]);

  React.useEffect(() => {
    if (router.pathname !== homepagePath || !pendingTargetRef.current) return;

    let frame = 0;
    let attempts = 0;
    const land = () => {
      const target = pendingTargetRef.current;
      if (target && scrollToTarget(target, "auto")) {
        pendingTargetRef.current = null;
        return;
      }

      if (attempts < 180) {
        attempts += 1;
        frame = window.requestAnimationFrame(land);
      }
    };

    frame = window.requestAnimationFrame(land);
    return () => window.cancelAnimationFrame(frame);
  }, [homepagePath, router.asPath, router.pathname]);

  React.useEffect(() => {
    if (!isOpen) return;

    const previousHtmlOverflow = document.documentElement.style.overflow;
    const previousBodyOverflow = document.body.style.overflow;
    document.documentElement.style.overflow = "hidden";
    document.body.style.overflow = "hidden";

    const focusables = (): HTMLElement[] =>
      [
        toggleRef.current,
        ...Array.from(
          panelRef.current?.querySelectorAll<HTMLElement>("a[href]") ?? [],
        ),
      ].filter((node): node is HTMLElement => Boolean(node));

    const focusFrame = window.requestAnimationFrame(() => {
      const currentLink = panelRef.current?.querySelector<HTMLElement>(
        'a[aria-current="page"]',
      );
      const firstLink = panelRef.current?.querySelector<HTMLElement>("a[href]");
      (currentLink ?? firstLink)?.focus();
    });

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        setIsOpen(false);
        return;
      }

      if (event.key !== "Tab") return;
      const focusableItems = focusables();
      if (!focusableItems.length) return;

      const first = focusableItems[0];
      const last = focusableItems[focusableItems.length - 1];
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last?.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first?.focus();
      }
    };

    document.addEventListener("keydown", onKeyDown);
    return () => {
      window.cancelAnimationFrame(focusFrame);
      document.removeEventListener("keydown", onKeyDown);
      document.documentElement.style.overflow = previousHtmlOverflow;
      document.body.style.overflow = previousBodyOverflow;
    };
  }, [isOpen]);

  React.useEffect(() => {
    if (!isOpen && wasOpenRef.current) toggleRef.current?.focus();
    wasOpenRef.current = isOpen;
  }, [isOpen]);

  const handleNavigation = (
    event: React.MouseEvent<HTMLAnchorElement>,
    item: CurvedMenuItem,
  ) => {
    setActiveHref(item.href);
    setSelectedHref(item.href);

    if (router.pathname === homepagePath && item.target) {
      event.preventDefault();
      setIsOpen(false);
      const targetUrl = new URL(window.location.href);
      targetUrl.hash = item.target === "home" ? "" : item.target;
      window.history.replaceState(
        window.history.state,
        "",
        targetUrl,
      );

      window.setTimeout(
        () => scrollToTarget(item.target!, reduceMotion ? "auto" : "smooth"),
        reduceMotion ? 0 : 360,
      );
      return;
    }

    pendingTargetRef.current = item.target ?? null;
    setIsOpen(false);
  };

  const motionState = reduceMotion
    ? { initial: false as const }
    : { initial: "initial", animate: "enter", exit: "exit" };
  const showToggle =
    router.pathname !== homepagePath ||
    revealAfterTarget === null ||
    hasReachedTrigger ||
    isOpen;

  return (
    <>
      <div
        className={`fixed right-5 top-5 z-[82] h-14 w-14 transition duration-300 motion-reduce:duration-0 sm:right-7 sm:top-7 sm:h-16 sm:w-16 ${
          showToggle
            ? "pointer-events-auto translate-y-0 scale-100 opacity-100"
            : "pointer-events-none -translate-y-3 scale-90 opacity-0"
        }`}
      >
        <motion.button
          ref={toggleRef}
          type="button"
          aria-label={isOpen ? "Close navigation" : "Open navigation"}
          aria-expanded={isOpen}
          aria-controls="site-navigation"
          aria-hidden={!showToggle}
          tabIndex={showToggle ? 0 : -1}
          onPointerMove={handleTogglePointerMove}
          onPointerLeave={resetTogglePosition}
          onPointerCancel={resetTogglePosition}
          onBlur={resetTogglePosition}
          onClick={() => setIsOpen((open) => !open)}
          style={reduceMotion ? undefined : { x: springX, y: springY }}
          whileTap={reduceMotion ? undefined : { scale: 0.97 }}
          className="group relative grid h-full w-full place-items-center overflow-hidden rounded-full bg-[#0c0c0e] text-[#fffafa] shadow-lg shadow-black/20 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/80 focus-visible:ring-offset-2 focus-visible:ring-offset-[#0c0c0e]"
        >
          <span className="sr-only">
            {isOpen ? "Close navigation" : "Open navigation"}
          </span>
          <span
            aria-hidden="true"
            className={`absolute -left-1/4 -top-1/2 h-[200%] w-[150%] rounded-full bg-white transition-transform duration-500 ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:duration-0 ${
              isOpen
                ? "translate-y-0"
                : "-translate-y-[78%] group-hover:translate-y-0 group-focus-visible:translate-y-0"
            }`}
          />
          <span aria-hidden="true" className="relative z-10 block h-4 w-6">
            <span
              className={`absolute left-0 top-[5px] h-px w-6 transition duration-300 motion-reduce:duration-0 ${
                isOpen
                  ? "translate-y-[3px] rotate-45 bg-[#0c0c0e]"
                  : "bg-current group-hover:bg-[#0c0c0e] group-focus-visible:bg-[#0c0c0e]"
              }`}
            />
            <span
              className={`absolute left-0 top-[11px] h-px w-6 transition duration-300 motion-reduce:duration-0 ${
                isOpen
                  ? "-translate-y-[3px] -rotate-45 bg-[#0c0c0e]"
                  : "bg-current group-hover:bg-[#0c0c0e] group-focus-visible:bg-[#0c0c0e]"
              }`}
            />
          </span>
        </motion.button>
      </div>

      <AnimatePresence mode="wait">
        {isOpen ? (
          <>
            <motion.div
              aria-hidden="true"
              className="fixed inset-0 z-[80] bg-black/25 backdrop-blur-[2px]"
              onPointerDown={() => setIsOpen(false)}
              variants={reduceMotion ? undefined : backdrop}
              {...motionState}
            />

            <motion.aside
              ref={panelRef}
              id="site-navigation"
              aria-label="Site navigation"
              className="fixed inset-y-0 right-0 z-[81] h-[100dvh] w-[min(460px,calc(100vw-44px))] bg-[#0c0c0e] text-[#fffafa] shadow-2xl shadow-black/25"
              variants={reduceMotion ? undefined : menuSlide}
              {...motionState}
            >
              <CurvedEdge reduceMotion={reduceMotion} />

              <div className="flex h-full flex-col overflow-x-hidden overflow-y-auto px-8 pb-8 pt-28 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden sm:px-12 sm:pb-10 sm:pt-32">
                <nav
                  className="flex flex-1 flex-col justify-center"
                  onMouseLeave={() => setSelectedHref(activeHref)}
                >
                  <p className="border-b border-white/20 pb-4 text-xs uppercase tracking-[0.16em] text-white/55">
                    {navigationLabel}
                  </p>
                  <ul className="mt-7 space-y-1">
                    {items.map((item, index) => {
                      const selected = selectedHref === item.href;
                      return (
                        <motion.li
                          key={item.href}
                          custom={index}
                          variants={reduceMotion ? undefined : linkSlide}
                          {...motionState}
                        >
                          <Link
                            href={item.href}
                            scroll={false}
                            onClick={(event) => handleNavigation(event, item)}
                            onMouseEnter={() => setSelectedHref(item.href)}
                            onFocus={() => setSelectedHref(item.href)}
                            aria-current={
                              activeHref === item.href ? "page" : undefined
                            }
                            className="group flex items-center gap-4 py-2 text-[length:clamp(2.4rem,8vw,4.4rem)] leading-[1.05] text-white/90 outline-none transition-colors hover:text-white focus-visible:text-white"
                          >
                            <motion.span
                              aria-hidden="true"
                              className="h-2.5 w-2.5 shrink-0 rounded-full bg-[#fffafa]"
                              animate={{
                                opacity: selected ? 1 : 0,
                                scale: selected ? 1 : 0,
                              }}
                              transition={{ duration: reduceMotion ? 0 : 0.25 }}
                            />
                            <span>{item.title}</span>
                          </Link>
                        </motion.li>
                      );
                    })}
                  </ul>
                </nav>
              </div>
            </motion.aside>
          </>
        ) : null}
      </AnimatePresence>
    </>
  );
}

export default CurvedMenu;

"use client";

import type { AnchorHTMLAttributes, ButtonHTMLAttributes, ReactNode } from "react";
import { ArrowLeft, ArrowRight } from "lucide-react";

type SharedProps = {
  text?: string;
  shape?: "pill" | "rectangle";
  direction?: "left" | "right";
  icon?: ReactNode;
  hoverIcon?: ReactNode;
};

export type FlowButtonProps = SharedProps & (
  | (ButtonHTMLAttributes<HTMLButtonElement> & { href?: undefined })
  | (AnchorHTMLAttributes<HTMLAnchorElement> & { href: string })
);

export function FlowButton({ text = "Modern Button", className, shape = "pill", direction = "right", icon, hoverIcon, ...props }: FlowButtonProps) {
  const disabled = "disabled" in props && props.disabled;
  const Arrow = direction === "left" ? ArrowLeft : ArrowRight;
  const rootClass = `relative inline-flex items-center justify-center gap-1 overflow-hidden ${shape === "rectangle" ? "rounded-md" : "rounded-full"} border-[1.5px] border-[#333333]/40 bg-transparent px-8 py-3 text-sm font-semibold text-[#111111] no-underline transition-all duration-[600ms] ease-[cubic-bezier(0.23,1,0.32,1)] motion-reduce:transition-none ${disabled ? "cursor-not-allowed opacity-50" : "group cursor-pointer hover:border-transparent hover:text-white focus-visible:text-white active:scale-[0.95] motion-reduce:active:scale-100"} ${className ?? ""}`;
  const incoming = direction === "left" ? "right-[-25%] group-hover:right-4 group-focus-visible:right-4" : "left-[-25%] group-hover:left-4 group-focus-visible:left-4";
  const outgoing = direction === "left" ? "left-4 group-hover:left-[-25%] group-focus-visible:left-[-25%]" : "right-4 group-hover:right-[-25%] group-focus-visible:right-[-25%]";
  const textFlow = direction === "left" ? "translate-x-3 group-hover:-translate-x-3 group-focus-visible:-translate-x-3" : "-translate-x-3 group-hover:translate-x-3 group-focus-visible:translate-x-3";
  const flowIconClass = "absolute z-[9] size-4 transition-all duration-[800ms] ease-[cubic-bezier(0.34,1.56,0.64,1)] motion-reduce:transition-none";
  const arrowClass = `${flowIconClass} fill-none stroke-[#111111] group-hover:stroke-white group-focus-visible:stroke-white`;
  const content = <>
    {hoverIcon ? (
      <span aria-hidden="true" className={`flow-button__incoming inline-flex items-center justify-center opacity-0 group-hover:opacity-100 group-focus-visible:opacity-100 [&>svg]:size-full ${flowIconClass} ${incoming}`}>{hoverIcon}</span>
    ) : (
      <Arrow aria-hidden="true" className={`flow-button__incoming ${arrowClass} ${incoming}`} />
    )}
    <span className={`flow-button__label relative z-[1] inline-flex items-center gap-2 whitespace-nowrap transition-all duration-[800ms] ease-out motion-reduce:transition-none ${textFlow}`}>
      {icon}{text}
    </span>
    <span aria-hidden="true" className="flow-button__fill absolute left-1/2 top-1/2 size-4 -translate-x-1/2 -translate-y-1/2 rounded-full bg-[#111111] opacity-0 transition-all duration-[800ms] ease-[cubic-bezier(0.19,1,0.22,1)] group-hover:size-[220px] group-hover:opacity-100 group-focus-visible:size-[220px] group-focus-visible:opacity-100 motion-reduce:transition-none" />
    <Arrow aria-hidden="true" className={`flow-button__outgoing ${arrowClass} ${outgoing} ${hoverIcon ? "group-hover:opacity-0 group-focus-visible:opacity-0" : ""}`} />
  </>;
  if (props.href !== undefined) return <a className={rootClass} {...props}>{content}</a>;
  return <button className={rootClass} {...props} type={props.type ?? "button"}>{content}</button>;
}

"use client";

import * as React from "react";

export type GradientPointerProps = {
  children?: React.ReactNode;
  className?: string;
  glow?: string;
  base?: string;
};

export function GradientPointer({ children, className, glow = "#f0ff8c", base = "#5528ff" }: GradientPointerProps) {
  const surface = React.useRef<HTMLDivElement>(null);
  const setPosition = (x: number, y: number) => {
    surface.current?.style.setProperty("--pointer-x", `${x}%`);
    surface.current?.style.setProperty("--pointer-y", `${y}%`);
  };
  const move = (event: React.PointerEvent<HTMLDivElement>) => {
    if (event.pointerType !== "mouse") return;
    const bounds = event.currentTarget.getBoundingClientRect();
    setPosition(((event.clientX - bounds.left) / bounds.width) * 100, ((event.clientY - bounds.top) / bounds.height) * 100);
  };

  return (
    <div
      ref={surface}
      className={`relative isolate overflow-hidden rounded-2xl ${className ?? ""}`}
      style={{
        "--pointer-x": "50%", "--pointer-y": "50%",
        background: `radial-gradient(circle at var(--pointer-x) var(--pointer-y), ${glow} 0%, ${base} 38%, #090909 78%)`,
      } as React.CSSProperties}
      onPointerMove={move}
      onPointerLeave={() => setPosition(50, 50)}
    >
      <div className="relative z-10">{children}</div>
    </div>
  );
}

"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";

export type BadgeImage = {
  src: string;
  alt: string;
};

export type ImagesBadgeProps = {
  images: BadgeImage[];
  maxVisible?: number;
  revealCount?: number;
  label?: string;
  size?: "sm" | "md" | "lg";
  shape?: "circle" | "rounded" | "square";
  className?: string;
  imageClassName?: string;
  labelClassName?: string;
  onClick?: React.MouseEventHandler<HTMLDivElement>;
};

const CONFIG = {
  sm: {
    pixels: 32,
    gap: 8,
    pill: "h-9 gap-2 pl-2 pr-3.5 text-[11px]",
    count: "text-[9px]",
  },
  md: {
    pixels: 42,
    gap: 10,
    pill: "h-11 gap-2.5 pl-2.5 pr-4 text-xs",
    count: "text-[10px]",
  },
  lg: {
    pixels: 56,
    gap: 12,
    pill: "h-14 gap-3 pl-3 pr-5 text-sm",
    count: "text-xs",
  },
} as const;

const SHAPES = {
  circle: "rounded-full",
  rounded: "rounded-[10px]",
  square: "rounded-[4px]",
} as const;

const SPRING = { type: "spring" as const, stiffness: 280, damping: 24 };
const REST_ROTATION = [-14, -7, -2, 5, 11, -9, 3, -5] as const;
const HOVER_ROTATION = [-8, -4, -1, 2, 6, -6, 2, -3] as const;

function classes(...values: Array<string | false | null | undefined>) {
  return values.filter(Boolean).join(" ");
}

function arcOffset(index: number, total: number, pixels: number) {
  if (total <= 1) return 0;
  const middle = (total - 1) / 2;
  const position = (index - middle) / middle;
  return position * position * (pixels * 0.22);
}

export function ImagesBadge({
  images,
  maxVisible = 3,
  revealCount = 2,
  label,
  size = "md",
  shape = "rounded",
  className,
  imageClassName,
  labelClassName,
  onClick,
}: ImagesBadgeProps) {
  const [hovered, setHovered] = React.useState(false);
  const reducedMotion = useReducedMotion();
  const { pixels, gap, pill, count } = CONFIG[size];

  const rendered = images.slice(0, maxVisible + revealCount);
  const overflow = Math.max(0, images.length - maxVisible - revealCount);
  const slots: Array<BadgeImage | null> =
    overflow > 0 ? [...rendered, null] : rendered;
  const total = slots.length;
  const peek = Math.round(pixels * 0.32);
  const collapsedWidth =
    total > 0 ? pixels + (Math.min(maxVisible, total) - 1) * peek : 0;
  const spreadWidth =
    total > 0 ? total * pixels + (total - 1) * gap : 0;

  const spreadX = (index: number) => index * (pixels + gap);
  const collapsedX = (index: number) =>
    index >= maxVisible ? (maxVisible - 1) * peek : index * peek;

  if (!total) return null;

  return (
    <motion.div
      className={classes(
        "inline-flex select-none items-center rounded-full border border-neutral-900/15 bg-[#fffafa] text-neutral-800 transition-[border-color] duration-300 motion-reduce:duration-0 hover:border-neutral-900/30 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-neutral-900/70 focus-visible:ring-offset-2 focus-visible:ring-offset-[#fffafa]",
        pill,
        onClick && "cursor-pointer",
        className,
      )}
      onHoverStart={() => setHovered(true)}
      onHoverEnd={() => setHovered(false)}
      onClick={onClick}
      whileHover={reducedMotion ? undefined : { y: -2, scale: 1.015 }}
      transition={SPRING}
      role={onClick ? "button" : undefined}
      tabIndex={onClick ? 0 : undefined}
      onKeyDown={
        onClick
          ? (event) => {
              if (event.key === "Enter" || event.key === " ") {
                event.preventDefault();
                event.currentTarget.click();
              }
            }
          : undefined
      }
    >
      <motion.div
        className="relative shrink-0"
        style={{ height: pixels + 12 }}
        animate={{
          width: reducedMotion
            ? spreadWidth
            : hovered
              ? spreadWidth
              : collapsedWidth,
        }}
        transition={SPRING}
      >
        {slots.map((image, index) => {
          const hidden = index >= maxVisible && image !== null;
          const isOverflow = image === null;
          const x = hovered ? spreadX(index) : collapsedX(index);
          const y = hovered ? arcOffset(index, total, pixels) : 0;
          const rotation = reducedMotion
            ? 0
            : hovered
              ? (HOVER_ROTATION[index] ?? 0)
              : (REST_ROTATION[index] ?? 0);

          return (
            <motion.div
              key={image?.src ?? `overflow-${overflow}`}
              className={classes(
                "absolute left-0 top-0 flex shrink-0 items-center justify-center border-2 border-[#fffafa] shadow-[0_3px_9px_rgba(23,23,23,0.24)]",
                !isOverflow && "overflow-hidden",
                SHAPES[isOverflow ? "circle" : shape],
                isOverflow && "bg-neutral-200",
                imageClassName,
              )}
              style={{
                width: pixels,
                height: pixels,
                zIndex: hovered ? index + 1 : total - index,
              }}
              animate={{
                x: reducedMotion ? spreadX(index) : x,
                y: reducedMotion ? 0 : y,
                rotate: rotation,
                opacity: hidden ? (hovered ? 1 : 0) : 1,
                scale: hidden ? (hovered ? 1 : 0.6) : 1,
              }}
              transition={{
                ...SPRING,
                delay:
                  !reducedMotion && hidden ? (index - maxVisible) * 0.06 : 0,
              }}
            >
              {isOverflow ? (
                <span className={classes("font-semibold text-neutral-600", count)}>
                  +{overflow}
                </span>
              ) : (
                <img
                  src={image.src}
                  alt={image.alt}
                  width={pixels}
                  height={pixels}
                  className="h-full w-full object-cover"
                  draggable={false}
                />
              )}
            </motion.div>
          );
        })}
      </motion.div>

      {label ? (
        <span
          className={classes(
            "whitespace-nowrap font-medium leading-none text-neutral-700",
            labelClassName,
          )}
        >
          {label}
        </span>
      ) : null}
    </motion.div>
  );
}

export default ImagesBadge;

"use client";

import * as React from "react";
import { motion, useAnimationFrame, useMotionValue, useReducedMotion } from "motion/react";

export type InfiniteMarqueeProps = {
  items: string[];
  speed?: number;
  separator?: React.ReactNode;
  className?: string;
};

export function InfiniteMarquee({ items, speed = 56, separator = "✦", className }: InfiniteMarqueeProps) {
  const group = React.useRef<HTMLDivElement>(null);
  const direction = React.useRef(-1);
  const x = useMotionValue(0);
  const reduceMotion = useReducedMotion();

  React.useEffect(() => {
    const onWheel = (event: WheelEvent) => {
      if (Math.abs(event.deltaY) > 2) direction.current = event.deltaY > 0 ? -1 : 1;
    };
    window.addEventListener("wheel", onWheel, { passive: true });
    return () => window.removeEventListener("wheel", onWheel);
  }, []);

  useAnimationFrame((_time, delta) => {
    if (reduceMotion || !group.current) return;
    const width = group.current.offsetWidth;
    if (!width) return;
    let next = x.get() + direction.current * speed * (delta / 1000);
    if (next <= -width) next += width;
    if (next > 0) next -= width;
    x.set(next);
  });

  const content = (hidden = false) => (
    <div ref={hidden ? undefined : group} className="flex shrink-0 items-center" aria-hidden={hidden || undefined}>
      {items.map((item, index) => (
        <React.Fragment key={`${item}-${index}`}>
          <span className="whitespace-nowrap px-[0.16em]">{item}</span>
          <span className="mx-[0.22em] text-[0.42em] opacity-50" aria-hidden="true">{separator}</span>
        </React.Fragment>
      ))}
    </div>
  );

  return (
    <div className={`w-full overflow-hidden ${className ?? ""}`} aria-label={items.join(", ")}>
      <motion.div className="flex w-max will-change-transform" style={{ x }}>
        {content()}{content(true)}
      </motion.div>
    </div>
  );
}

"use client";

import * as React from "react";
import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Variants,
} from "motion/react";

function cn(...classes: Array<string | undefined | null | false>) {
  return classes.filter(Boolean).join(" ");
}

export type LandingGreetProps = {
  /** Page content. When provided, it gets the same parallax settle as
   *  curve-page-transition: it rises into place as the sweep reveals it. */
  children?: React.ReactNode;

  /** Page background color behind the content (children mode) */
  backgroundColor?: string;

  /** Greetings to cycle through before the sweep */
  words?: string[];

  /** How long the first word holds (ms) */
  firstWordMs?: number;

  /** How long each subsequent word holds (ms) */
  wordMs?: number;

  /** Pause on the last word before the sweep starts (ms) */
  holdMs?: number;

  /** Overlay color */
  curveColor?: string;

  className?: string;

  /** Fires once the sweep finishes and the overlay unmounts */
  onComplete?: () => void;
};

const DEFAULT_WORDS = [
  "Hello",
  "Hola",
  "Bonjour",
  "Hei",
  "Dia dhuit",
  "Привет",
  "안녕하세요",
  "こんにちは",
  "你好",
  "Kamusta",
];

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect;

// NOTE: the overlay animates `y` (a compositor-friendly transform), never
// `top` — animating layout properties on viewport-sized elements drops frames.

const opacity: Variants = {
  initial: { opacity: 0 },
  enter: { opacity: 0.75, transition: { duration: 1, delay: 0.2 } },
};

const slideUp = (viewportH: number): Variants => ({
  initial: { y: 0 },
  exit: {
    y: -viewportH,
    transition: { duration: 0.8, ease: [0.76, 0, 0.24, 1], delay: 0.2 },
  },
});

const curve = (initialPath: string, targetPath: string): Variants => ({
  initial: { d: initialPath },
  exit: {
    d: targetPath,
    transition: { duration: 0.7, ease: [0.76, 0, 0.24, 1], delay: 0.3 },
  },
});

// same parallax as curve-page-transition's content: the page settles upward
// into place while the sweep reveals it
const content: Variants = {
  covered: { y: 150 },
  revealed: {
    y: 0,
    transition: { duration: 1, delay: 0.35, ease: [0.16, 1, 0.3, 1] },
  },
};

/**
 * Awwwards-style intro preloader, after Olivier Larose's landing page
 * tutorial: a dark cover cycles through greetings, then sweeps upward off the
 * page with a curved trailing edge. Self-contained — drop `<LandingGreet />`
 * anywhere in the page; no AnimatePresence wiring needed in _app.
 */
export function LandingGreet({
  children,
  backgroundColor,
  words = DEFAULT_WORDS,
  firstWordMs = 1000,
  wordMs = 150,
  holdMs = 400,
  curveColor = "black",
  className,
  onComplete,
}: LandingGreetProps) {
  const reduceMotion = useReducedMotion();
  const [index, setIndex] = React.useState(0);
  const [done, setDone] = React.useState(() => words.length === 0);
  const [dimensions, setDimensions] = React.useState<{
    width: number | null;
    height: number | null;
  }>({ width: null, height: null });

  useIsomorphicLayoutEffect(() => {
    const measure = () =>
      setDimensions({ width: window.innerWidth, height: window.innerHeight });
    measure();
    window.addEventListener("resize", measure);
    return () => window.removeEventListener("resize", measure);
  }, []);

  // reduced-motion users skip the intro entirely
  React.useEffect(() => {
    if (reduceMotion) setDone(true);
  }, [reduceMotion]);

  // cycle the greetings, then trigger the sweep
  React.useEffect(() => {
    if (done || !words.length) return;
    const last = index === words.length - 1;
    const t = window.setTimeout(
      () => (last ? setDone(true) : setIndex((i) => i + 1)),
      last ? holdMs : index === 0 ? firstWordMs : wordMs,
    );
    return () => window.clearTimeout(t);
  }, [index, done, words.length, firstWordMs, wordMs, holdMs]);

  // lock page scroll while the overlay is up
  React.useEffect(() => {
    if (done) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = prev;
    };
  }, [done]);

  const { width, height } = dimensions;

  // same responsive treatment as curve-page-transition: lip depth scales
  // with viewport width, and paths overshoot 5px past both horizontal edges
  // so subpixel rounding never exposes a hairline gap
  const depth =
    width === null
      ? 300
      : Math.min(300, Math.round(width / (width < 640 ? 6 : 4)));

  const hasSize = width !== null && height !== null;
  const initialPath = hasSize
    ? `M-5 0 L${width + 5} 0 L${width + 5} ${height} Q${width / 2} ${
        height + depth
      } -5 ${height} L-5 0`
    : "";
  const targetPath = hasSize
    ? `M-5 0 L${width + 5} 0 L${width + 5} ${height} Q${width / 2} ${height} -5 ${height} L-5 0`
    : "";

  const overlay = (
    <AnimatePresence mode="wait" onExitComplete={() => onComplete?.()}>
      {!done && (
        <motion.div
          className={cn(
            "fixed inset-0 z-[99] flex items-center justify-center",
            children === undefined && className,
          )}
          style={{ backgroundColor: curveColor, willChange: "transform" }}
          variants={slideUp(height ?? 800)}
          initial="initial"
          exit="exit"
        >
          {hasSize && (
            <>
              {/* curved lip hanging below the viewport; flattens as it exits */}
              <svg
                className="pointer-events-none absolute"
                style={{
                  top: 0,
                  left: -5,
                  width: "calc(100vw + 10px)",
                  height: `calc(100vh + ${depth}px)`,
                }}
              >
                <motion.path
                  fill={curveColor}
                  variants={curve(initialPath, targetPath)}
                  initial="initial"
                  exit="exit"
                />
              </svg>
              <motion.p
                className="relative z-10 text-[length:clamp(1.5rem,5vw,2.875rem)] font-medium text-white"
                variants={opacity}
                initial="initial"
                animate="enter"
              >
                {words[index]}
              </motion.p>
            </>
          )}
        </motion.div>
      )}
    </AnimatePresence>
  );

  // overlay-only mode: drop the component next to your content
  if (children === undefined) return overlay;

  // children mode: wraps the page like curve-page-transition, so the content
  // settles upward into place while the sweep reveals it. overflow-y-clip
  // keeps the parallax offset from flashing a scrollbar (transformed boxes
  // count toward scrollable overflow).
  return (
    <div
      className={cn("relative min-h-screen overflow-y-clip", className)}
      style={{ backgroundColor }}
    >
      {overlay}
      <motion.div
        variants={content}
        initial={reduceMotion ? false : "covered"}
        animate={done ? "revealed" : "covered"}
      >
        {children}
      </motion.div>
    </div>
  );
}

"use client";

import * as React from "react";
import { motion, useMotionValue, useReducedMotion, useSpring } from "motion/react";

export type MagneticButtonProps = Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onPointerMove" | "onPointerLeave"> & {
  strength?: number;
};

export function MagneticButton({ strength = 0.3, className, children, ...props }: MagneticButtonProps) {
  const xTarget = useMotionValue(0);
  const yTarget = useMotionValue(0);
  const x = useSpring(xTarget, { stiffness: 210, damping: 18, mass: 0.35 });
  const y = useSpring(yTarget, { stiffness: 210, damping: 18, mass: 0.35 });
  const reduceMotion = useReducedMotion();

  const reset = () => { xTarget.set(0); yTarget.set(0); };
  const move = (event: React.PointerEvent<HTMLButtonElement>) => {
    if (reduceMotion || event.pointerType !== "mouse") return;
    const bounds = event.currentTarget.getBoundingClientRect();
    xTarget.set((event.clientX - bounds.left - bounds.width / 2) * strength);
    yTarget.set((event.clientY - bounds.top - bounds.height / 2) * strength);
  };

  return (
    <motion.span className="inline-block" style={{ x, y }}>
      <button
        {...props}
        type={props.type ?? "button"}
        className={`inline-flex min-h-11 items-center justify-center rounded-md bg-white px-7 py-3 text-sm font-semibold text-black outline-none ring-white/70 transition-colors hover:bg-neutral-200 focus-visible:ring-4 disabled:cursor-not-allowed disabled:opacity-50 ${className ?? ""}`}
        onPointerMove={move}
        onPointerLeave={reset}
        onBlur={reset}
      >
        {children}
      </button>
    </motion.span>
  );
}

"use client";

import * as React from "react";

export type PaintRevealProps = {
  children?: React.ReactNode;
  cover?: string;
  brushSize?: number;
  className?: string;
};

export function PaintReveal({ children, cover = "#f4f0e8", brushSize = 72, className }: PaintRevealProps) {
  const canvas = React.useRef<HTMLCanvasElement>(null);
  const drawing = React.useRef(false);
  const previous = React.useRef<{ x: number; y: number } | null>(null);

  const reset = React.useCallback(() => {
    const node = canvas.current;
    if (!node) return;
    const bounds = node.getBoundingClientRect();
    const ratio = Math.min(window.devicePixelRatio || 1, 2);
    node.width = Math.max(1, Math.round(bounds.width * ratio));
    node.height = Math.max(1, Math.round(bounds.height * ratio));
    const context = node.getContext("2d");
    if (!context) return;
    context.setTransform(ratio, 0, 0, ratio, 0, 0);
    context.globalCompositeOperation = "source-over";
    context.fillStyle = cover;
    context.fillRect(0, 0, bounds.width, bounds.height);
  }, [cover]);

  React.useEffect(() => {
    reset();
    const observer = new ResizeObserver(reset);
    if (canvas.current) observer.observe(canvas.current);
    return () => observer.disconnect();
  }, [reset]);

  const point = (event: React.PointerEvent<HTMLCanvasElement>) => {
    const bounds = event.currentTarget.getBoundingClientRect();
    return { x: event.clientX - bounds.left, y: event.clientY - bounds.top };
  };
  const erase = (event: React.PointerEvent<HTMLCanvasElement>) => {
    if (!drawing.current) return;
    const node = event.currentTarget;
    const context = node.getContext("2d");
    if (!context) return;
    const next = point(event);
    const last = previous.current ?? next;
    context.globalCompositeOperation = "destination-out";
    context.lineCap = "round";
    context.lineJoin = "round";
    context.lineWidth = brushSize;
    context.beginPath();
    context.moveTo(last.x, last.y);
    context.lineTo(next.x, next.y);
    context.stroke();
    previous.current = next;
  };
  const finish = (event: React.PointerEvent<HTMLCanvasElement>) => {
    drawing.current = false;
    previous.current = null;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
  };

  return (
    <div className={`relative isolate min-h-80 overflow-hidden rounded-2xl bg-black ${className ?? ""}`}>
      <div className="absolute inset-0 flex items-center justify-center p-8 text-center text-white">{children}</div>
      <canvas
        ref={canvas}
        className="absolute inset-0 size-full cursor-crosshair touch-none"
        aria-label="Paint away the cover to reveal the content"
        onPointerDown={(event) => { drawing.current = true; previous.current = point(event); event.currentTarget.setPointerCapture(event.pointerId); erase(event); }}
        onPointerMove={erase}
        onPointerUp={finish}
        onPointerCancel={finish}
      />
      <button type="button" className="absolute right-4 top-4 z-10 min-h-11 rounded-md bg-black px-4 text-xs font-semibold text-white ring-white/70 focus-visible:outline-none focus-visible:ring-4" onClick={reset}>Reset</button>
    </div>
  );
}

"use client";

import * as React from "react";
import Link from "next/link";
import { ArrowUpRight } from "lucide-react";
import {
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
} from "motion/react";

export type ProjectShowcaseItem = {
  title: string;
  link: string;
  description?: string | null;
  year?: string | null;
  image?: string | null;
  imageSrcSet?: string;
};

export type ProjectShowcaseProps = {
  projects?: ProjectShowcaseItem[];
  className?: string;
  emptyMessage?: string;
};

const PREVIEW_WIDTH = 320;
const PREVIEW_HEIGHT = 200;
const FOLLOW_SPRING = { stiffness: 230, damping: 28, mass: 0.45 };

function clamp(value: number, minimum: number, maximum: number) {
  return Math.min(Math.max(value, minimum), maximum);
}

export function ProjectShowcase({
  projects = [],
  className = "",
  emptyMessage = "No projects have been published yet.",
}: ProjectShowcaseProps) {
  const [hoveredIndex, setHoveredIndex] = React.useState<number | null>(null);
  const [previewVisible, setPreviewVisible] = React.useState(false);
  const reducedMotion = useReducedMotion();
  const previewX = useMotionValue(0);
  const previewY = useMotionValue(0);
  const smoothX = useSpring(previewX, FOLLOW_SPRING);
  const smoothY = useSpring(previewY, FOLLOW_SPRING);

  const handlePointerMove = React.useCallback(
    (event: React.PointerEvent<HTMLElement>) => {
      if (reducedMotion || event.pointerType !== "mouse") return;

      previewX.set(
        clamp(event.clientX + 24, 16, window.innerWidth - PREVIEW_WIDTH - 16),
      );
      previewY.set(
        clamp(
          event.clientY - PREVIEW_HEIGHT / 2,
          16,
          window.innerHeight - PREVIEW_HEIGHT - 16,
        ),
      );
    },
    [previewX, previewY, reducedMotion],
  );

  const handlePointerEnter = (
    event: React.PointerEvent<HTMLAnchorElement>,
    index: number,
  ) => {
    setHoveredIndex(index);
    if (event.pointerType === "mouse" && !reducedMotion) {
      setPreviewVisible(true);
    }
  };

  const clearPointerPreview = () => {
    setHoveredIndex(null);
    setPreviewVisible(false);
  };

  if (!projects.length) {
    return (
      <section
        aria-label="Projects"
        className={`mx-auto w-full max-w-[1200px] px-6 pb-28 sm:px-10 sm:pb-36 lg:px-12 ${className}`}
      >
        <p className="border-t border-neutral-900/20 py-10 text-base text-neutral-600">
          {emptyMessage}
        </p>
      </section>
    );
  }

  return (
    <section
      aria-label="Projects"
      onPointerMove={handlePointerMove}
      className={`relative mx-auto w-full max-w-[1200px] px-6 pb-28 sm:px-10 sm:pb-36 lg:px-12 ${className}`}
    >
      <motion.div
        aria-hidden="true"
        className="pointer-events-none fixed left-0 top-0 z-[70] hidden overflow-hidden rounded-xl bg-[#0c0c0e] shadow-[0_24px_70px_rgba(0,0,0,0.42)] lg:block"
        style={{
          width: PREVIEW_WIDTH,
          height: PREVIEW_HEIGHT,
          x: reducedMotion ? previewX : smoothX,
          y: reducedMotion ? previewY : smoothY,
        }}
        initial={false}
        animate={{
          opacity: previewVisible ? 1 : 0,
          scale: previewVisible ? 1 : 0.92,
        }}
        transition={{
          duration: reducedMotion ? 0 : 0.28,
          ease: [0.16, 1, 0.3, 1],
        }}
      >
        {projects.map((project, index) =>
          project.image ? (
            <motion.img
              key={project.title}
              src={project.image}
              srcSet={project.imageSrcSet}
              sizes={`${PREVIEW_WIDTH}px`}
              alt=""
              width={PREVIEW_WIDTH}
              height={PREVIEW_HEIGHT}
              loading={index === 0 ? "eager" : "lazy"}
              decoding="async"
              className="absolute inset-0 h-full w-full object-cover"
              animate={{
                opacity: hoveredIndex === index ? 1 : 0,
                scale: hoveredIndex === index && !reducedMotion ? 1 : 1.06,
              }}
              transition={{
                duration: reducedMotion ? 0 : 0.45,
                ease: [0.16, 1, 0.3, 1],
              }}
            />
          ) : null,
        )}
      </motion.div>

      <div className="border-b border-neutral-900/20">
        {projects.map((project, index) => {
          const active = hoveredIndex === index;

          return (
            <Link
              key={project.title}
              href={project.link}
              scroll={false}
              onPointerEnter={(event) => handlePointerEnter(event, index)}
              onPointerLeave={clearPointerPreview}
              onFocus={() => setHoveredIndex(index)}
              onBlur={() => setHoveredIndex(null)}
              className="group relative block border-t border-neutral-900/20 py-7 outline-none transition-[padding] duration-300 motion-reduce:duration-0 focus-visible:px-3 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-neutral-900/75 sm:py-9 lg:hover:px-3"
            >
              <span
                aria-hidden="true"
                className={`absolute inset-0 bg-black/[0.035] transition-opacity duration-300 motion-reduce:duration-0 ${
                  active ? "opacity-100" : "opacity-0"
                }`}
              />

              {project.image ? (
                <img
                  src={project.image}
                  srcSet={project.imageSrcSet}
                  sizes="(min-width: 1024px) 0px, calc(100vw - 48px)"
                  alt=""
                  width={960}
                  height={600}
                  loading={index === 0 ? "eager" : "lazy"}
                  decoding="async"
                  className="relative mb-6 aspect-[16/10] w-full rounded-xl object-cover lg:hidden"
                />
              ) : null}

              <div className="relative flex items-start justify-between gap-6">
                <div className="min-w-0 flex-1">
                  <div className="inline-flex items-center gap-3">
                    <h2 className="text-2xl leading-tight text-neutral-900 sm:text-4xl">
                      <span className="relative inline-block">
                        {project.title}
                        <span
                          aria-hidden="true"
                          className={`absolute inset-x-0 -bottom-1 h-px origin-left bg-neutral-900 transition-transform duration-300 motion-reduce:duration-0 ${
                            active ? "scale-x-100" : "scale-x-0"
                          }`}
                        />
                      </span>
                    </h2>
                    <ArrowUpRight
                      aria-hidden="true"
                      strokeWidth={1.5}
                      className={`h-5 w-5 shrink-0 text-neutral-900/65 transition duration-300 motion-reduce:duration-0 ${
                        active
                          ? "translate-x-0 translate-y-0 opacity-100"
                          : "-translate-x-2 translate-y-2 opacity-0"
                      }`}
                    />
                  </div>
                  {project.description ? (
                    <p className="mt-2 max-w-[58ch] text-sm leading-relaxed text-neutral-600 sm:text-base">
                      {project.description}
                    </p>
                  ) : null}
                </div>

                {project.year ? (
                  <span className="shrink-0 pt-1 text-xs tabular-nums text-neutral-500 sm:text-sm">
                    {project.year}
                  </span>
                ) : null}
              </div>
            </Link>
          );
        })}
      </div>
    </section>
  );
}

export default ProjectShowcase;

"use client";

import * as React from "react";
import { useReducedMotion } from "motion/react";

export type TextScrollRevealProps = {
  text: string;
  className?: string;
  height?: number;
};

export function TextScrollReveal({ text, className, height = 620 }: TextScrollRevealProps) {
  const words = React.useMemo(() => text.trim().split(/\s+/), [text]);
  const [progress, setProgress] = React.useState(0);
  const reduceMotion = useReducedMotion();
  const onScroll = (event: React.UIEvent<HTMLDivElement>) => {
    const node = event.currentTarget;
    const range = node.scrollHeight - node.clientHeight;
    setProgress(range > 0 ? node.scrollTop / range : 1);
  };

  return (
    <div
      className={`relative overflow-y-auto overscroll-contain ${className ?? ""}`}
      style={{ height }}
      onScroll={onScroll}
      tabIndex={0}
      data-lenis-prevent
      aria-label={`${text}. Scroll to reveal the text.`}
    >
      <div className="h-[220%]">
        <p className="sticky top-0 flex min-h-full flex-wrap content-center px-6 py-20 text-[clamp(2rem,6vw,5.5rem)] font-semibold leading-[0.98] tracking-[-0.04em]" aria-hidden="true">
          {words.map((word, index) => {
            const start = (index / Math.max(words.length, 1)) * 0.72;
            const opacity = reduceMotion ? 1 : Math.max(0.16, Math.min(1, (progress - start) * 7 + 0.16));
            return <span key={`${word}-${index}`} className="mr-[0.22em] transition-opacity duration-150" style={{ opacity }}>{word}</span>;
          })}
        </p>
      </div>
    </div>
  );
}
